config.command:
set -euo pipefail
cd "{{ project_path }}"
SINCE="{{ since }}"
echo "=== Lines Changed per Author ==="
git log --since="$SINCE" --format='%aN' --numstat | python3 -c "
import sys
authors = {}
current = None
for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    parts = line.split('\t')
    if len(parts) == 1:
        current = line
        if current not in authors:
            authors[current] = {'added': 0, 'deleted': 0}
    elif len(parts) == 3 and current:
        try:
            authors[current]['added'] += int(parts[0])
            authors[current]['deleted'] += int(parts[1])
        except ValueError:
            pass
for name, stats in sorted(authors.items(), key=lambda x: x[1]['added'], reverse=True):
    print(f'{name}: +{stats[\"added\"]} -{stats[\"deleted\"]}')" 2>&1
